// D2.4 — boundary request adapter conformance.
//
// The backend dumps canonical `BatchSolverRequest` / `WaterSolverRequest` bodies
// (`tests/conformance/fixtures/*.json`, regenerated by
// `tests/backend/conformance/test_boundary_fixtures.py`). Here we rebuild the
// SAME bodies from a matching host state and assert deep-equality plus
// fingerprint parity against the backend's `canonical_fingerprint`.

import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import {
  buildBatchRequest,
  buildHopRequest,
  buildWaterRequest,
} from "../../frontend/src/adapters/boundaryRequest.js";
import { canonicalFingerprint } from "../../frontend/src/engine/boundary.js";

function fixture(name) {
  return JSON.parse(readFileSync(new URL(`./fixtures/${name}.json`, import.meta.url), "utf8"));
}

// The raw FRONTEND grist rows the engine resolves (pct already Hamilton-normalized).
const GRIST = [
  { catalog_id: "pilsner", name: "Pilsner", category: "BASE", parts: 80, pct: 0.8, yield_fraction: 0.8, fermentability_fraction: 0.643, fermentability_basis: "real", color_lovibond: 1.5 },
  { catalog_id: "crystal-40", name: "Crystal 40", category: "CRYSTAL", parts: 20, pct: 0.2, yield_fraction: 0.74, fermentability_fraction: 0.398, fermentability_basis: "real", color_lovibond: 40 },
];

const M_GRIST = 4.7;

// A matching engine state: only the paths the builders read, resolving to the
// canonical values. An unexpected path throws, so adapter-path drift is caught.
function stubEngine(
  values,
  { traceRows = [], hopBoilRows = [], hopWhirlpoolRows = [] } = {}
) {
  return {
    get(id) {
      if (id === "grist.major_malts") return GRIST;
      if (id === "grist.trace_malts") return traceRows;
      if (id === "water.pinned_ions") return [];
      if (id === "batch.boil_hops") return hopBoilRows;
      if (id === "batch.whirlpool_hops") return hopWhirlpoolRows;
      throw new Error(`unexpected get("${id}")`);
    },
    resolve(path) {
      if (!(path in values)) throw new Error(`unexpected resolve("${path}")`);
      return values[path];
    },
  };
}

const BATCH_VALUES = {
  "batch.target_abv": 5.5,
  "batch.yeast_cap": 0.75,
  "batch.yeast.sta1": false,  "batch.grain_moisture_fraction": 0.04,
  "batch.v_ferm": 20.0,
  "batch.topology": "r_l_to_g",
  "batch.mash_thickness_l_per_kg": 3.0,
  "batch.runoff_ratio": 1.0,
  "batch.s_late_add": 0.0,
  "batch.s_late_add_request": 0.0,
  "batch.sugar_share_request": 0.0,
  "equipment.kettle_dead_space_l": 0.0,
  "equipment.kettle_transfer_loss_l": 0.0,
  "equipment.trub_loss_l": 0.0,
  "batch.delta_v_evap": 3.0,
  "equipment.mash_dead_space_l": 0.0,
  "equipment.mash_transfer_loss_l": 0.0,
  "equipment.grain_absorption_factor_l_per_kg": 1.043176,
  "batch.conversion_efficiency": 0.95,
  "equipment.shrinkage_pct": 0.04,
  "batch.hlt_starting_volume_l": 25.0,
  "equipment.hlt_dead_space_l": 0.0,
  "equipment.hlt_transfer_loss_l": 0.0,
  "equipment.hlt_coil_floor_l": 0.0,
  "equipment.max_hlt_volume_l": 30.0,
  "equipment.max_kettle_volume_l": 40.0,
  "equipment.max_mash_tun_volume_l": 40.0,
};

const WATER_VALUES = {
  "solver.batch.m_grist": M_GRIST,
  "water.source.calcium_ca": 20.0,
  "water.source.magnesium_mg": 5.0,
  "water.source.sodium_na": 10.0,
  "water.source.sulfate_so4": 30.0,
  "water.source.chloride_cl": 15.0,
  "water.source.total_alkalinity_caco3": 80.0,
  "water.target.calcium_ca": 60.0,
  "water.target.magnesium_mg": 10.0,
  "water.target.sodium_na": 20.0,
  "water.target.sulfate_so4": 100.0,
  "water.target.chloride_cl": 50.0,
  "water.target.alkalinity_as_caco3": 40.0,
  "solver.batch.cascade.v_strike": 14.0,
  "batch.sparge_salted_volume": 15.0,
  "solver.batch.hlt.v_hlt_debt": 1.0,
  "solver.batch.cascade.v_sparge": 14.0,
  "solver.batch.mash_thickness_l_per_kg": 3.0,
  "water.target_mash_ph": 5.4,
  "water.strategy": "CALCIUM_FLOOR",
  "water.salt_distribution": "PROPORTIONAL",
  "water.acid_medium": "LACTIC_88",
  "water.gypsum_form": "GYPSUM_DIHYDRATE",
  "water.cacl2_form": "CACL2_DIHYDRATE",
  "water.preferred_alkaline_agent": "PICKLING_LIME",
  "water.calcium_floor_ppm": 50.0,
};

test("conformance: adapted BatchSolverRequest matches the backend dump", () => {
  const { request, fingerprint } = fixture("batch");
  const body = buildBatchRequest(stubEngine(BATCH_VALUES));
  assert.deepEqual(body, request);
  assert.equal(canonicalFingerprint(body), fingerprint);
});

const HOP_VALUES = {
  "batch.boil_target_ibu": 40.0,
  "batch.whirlpool_target_ibu": 20.0,
  "batch.boil_time_min": 60.0,
  "solver.batch.cascade.sg_pre_boil": 1.048,
  "solver.batch.sg_post_boil": 1.055,
  "solver.batch.cascade.v_post_boil": 21.0,
  "batch.whirlpool_ambient_temp_c": 20.0,
  "batch.whirlpool_cooling_time_constant_min": 108.7,
};

const HOP_BOIL_ROWS = [
  { alpha_acid_pct: 0.1, boil_time_fraction: 1.0, pct: 0.6 },
  { alpha_acid_pct: 0.12, boil_time_fraction: 0.5, pct: 0.4 },
];

const HOP_WHIRLPOOL_ROWS = [
  {
    alpha_acid_pct: 0.1,
    duration_min: 30.0,
    initial_temp_c: 99.0,
    pct: 1.0,
    product_form: "t90_pellet",
  },
];

test("conformance: adapted HopSolverRequest matches the backend dump", () => {
  const { request, fingerprint } = fixture("hop");
  const body = buildHopRequest(
    stubEngine(HOP_VALUES, {
      hopBoilRows: HOP_BOIL_ROWS,
      hopWhirlpoolRows: HOP_WHIRLPOOL_ROWS,
    })
  );
  assert.deepEqual(body, request);
  assert.equal(canonicalFingerprint(body), fingerprint);
});

test("conformance: adapted WaterSolverRequest matches the backend dump", () => {
  const { request, fingerprint } = fixture("water");
  const body = buildWaterRequest(stubEngine(WATER_VALUES));
  assert.deepEqual(body, request);
  assert.equal(canonicalFingerprint(body), fingerprint);
});

test("water request appends trace malts by definite mass; drops zero-mass rows", () => {
  const trace = [
    { catalog_id: "black", name: "Black Malt", category: "ROASTED", mass_kg: 0.17, yield_fraction: 0.55, color_lovibond: 500 },
    { catalog_id: "empty", name: "Untouched", category: "ROASTED", mass_kg: 0, yield_fraction: 0.55, color_lovibond: 500 },
  ];
  const body = buildWaterRequest(stubEngine(WATER_VALUES, { traceRows: trace }));
  assert.deepEqual(body.grist, [
    { mass_kg: 0.8 * M_GRIST, color_lovibond: 1.5, grain_type: "BASE" },
    { mass_kg: 0.2 * M_GRIST, color_lovibond: 40, grain_type: "CRYSTAL" },
    { mass_kg: 0.17, color_lovibond: 500, grain_type: "ROASTED" },
  ]);
});
